import{_ as a,C as o,o as i,c as r,j as t,a as n,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/vscode-run-control-code.png",y=JSON.parse(`{"title":"Code from a pause","description":"At a test paused or failed in a run Piwi started from VS Code or a JetBrains IDE, write an assertion, a region's ARIA snapshot or a mock of a request the page made above the stopped line, pick a locator or record steps there, and see how many elements the locator at the cursor matches on the stopped page.","frontmatter":{"title":"Code from a pause","description":"At a test paused or failed in a run Piwi started from VS Code or a JetBrains IDE, write an assertion, a region's ARIA snapshot or a mock of a request the page made above the stopped line, pick a locator or record steps there, and see how many elements the locator at the cursor matches on the stopped page.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-stop-code.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-stop-code.html"}],["meta",{"property":"og:title","content":"Code from a pause | Piwi Dashboard"}],["meta",{"property":"og:description","content":"At a test paused or failed in a run Piwi started from VS Code or a JetBrains IDE, write an assertion, a region's ARIA snapshot or a mock of a request the page made above the stopped line, pick a locator or record steps there, and see how many elements the locator at the cursor matches on the stopped page."}]]},"headers":[],"relativePath":"features/editor-stop-code.md","filePath":"features/editor-stop-code.md","lastUpdated":1793445642000}`),c={name:"features/editor-stop-code.md"};function p(u,e,g,k,m,f){const s=o("Needs");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"code-from-a-pause",tabindex:"-1"},[n("Code from a pause "),t("a",{class:"header-anchor",href:"#code-from-a-pause","aria-label":'Permalink to "Code from a pause"'},"​")],-1)),h(s,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>When a test stops in a run the <a href="./editors.html">editor extensions</a> started, at a breakpoint, after <strong>Pause</strong> or <strong>Step</strong>, or at a failure, the editor offers code written from the page as it stands: an assertion of what you see, a mock of a request the page made, a better locator, the missing steps. The work on the page happens in the test&#39;s own browser; the editor service writes the code, and the editor puts it above the stopped line. The controls that move the test are on <a href="./editor-run-control.html">Pause and step from the editor</a>.</p><h2 id="the-actions" tabindex="-1">The actions <a class="header-anchor" href="#the-actions" aria-label="Permalink to &quot;The actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What is written</th><th>Where it runs</th></tr></thead><tbody><tr><td><strong>Pick a locator</strong></td><td>The locator of the element you pick, in place of the locator chain on the stopped line</td><td>The test&#39;s window, as the pause bar&#39;s <a href="./editor-breakpoints.html#where-the-pick-lands">Pick a locator</a></td></tr><tr><td><strong>Record here</strong></td><td>The steps you take, above the stopped line</td><td>The test&#39;s window, as the bar&#39;s <a href="./editor-breakpoints.html#record-from-a-pause">Record here</a></td></tr><tr><td><strong>Assert</strong></td><td>The check you choose in the recorder&#39;s check panel, <code>await expect(…).toHaveText(…)</code> and the like</td><td>The test&#39;s window</td></tr><tr><td><strong>Assert a region</strong></td><td><code>await expect(…).toMatchAriaSnapshot(…)</code> with the ARIA snapshot of the region you pick</td><td>The test&#39;s window</td></tr><tr><td><strong>Mock a request</strong></td><td><code>await page.route(…)</code> that answers as the server answered a request the page made</td><td>The editor alone, at any stop</td></tr></tbody></table><p>The first four need the pause bar, so a headed browser: a run Piwi starts with breakpoints is headed. <strong>Mock a request</strong> works headless too.</p><ul><li><strong>In VS Code</strong>, they are in the line above the stopped line, after the controls (named <strong>Pick</strong>, <strong>Record</strong>, <strong>Assert</strong>, <strong>Assert region</strong> and <strong>Mock</strong> there), in its hover, in the palette while a stop offers them (<strong>Piwi: Assert in the stopped test&#39;s page</strong>, <strong>Piwi: Mock a request of the stopped test</strong>…), and behind the status bar&#39;s <code>&lt;/&gt;</code> item, <strong>Piwi: Write code at the stop…</strong>.</li><li><strong>In a JetBrains IDE</strong>, they are links in the inlay above the stopped line (by the same short names), in the gutter icon&#39;s menu, first in the status bar item&#39;s menu, and under <strong>Tools → Piwi</strong> (<strong>Assert at the Stop</strong>, <strong>Mock a Request at the Stop</strong>…).</li></ul><p>None has a default key: bind one in <strong>Preferences: Open Keyboard Shortcuts</strong> or <strong>Settings → Keymap</strong> (search <code>piwi</code>). A stop offers only the actions its reporter takes: with one that predates them, none.</p><figure><img src="'+l+`" alt="VS Code: a test paused before it types a coupon; above the line, the controls then Pick, Record, Assert, Assert region and Mock; at the line&#39;s end, Piwi: 1 match; at the top, the list of the requests the test made, to mock one"><figcaption>Mock a request lists the answers the test received; the line&#39;s locator matches one element on the paused page.</figcaption></figure><h2 id="where-the-code-goes" tabindex="-1">Where the code goes <a class="header-anchor" href="#where-the-code-goes" aria-label="Permalink to &quot;Where the code goes&quot;">​</a></h2><p>The code goes on a new line above the stopped statement (the first line of a statement broken over lines), indented for it, on the page in scope there (<code>this.page</code> in a page object), with the import of <code>expect</code> the file lacks, as one edit that one undo takes away. A second action at the same stop goes above the same statement, under the first. The running test goes on with the code it started with: the new lines run next time, which the first code of a run says.</p><p>Nothing is written, and the editor says why, at a stop:</p><ul><li>outside a test&#39;s or a function&#39;s body, such as a test timeout stopped at its <code>test(</code> line;</li><li>as the body of an <code>if</code>, <code>else</code>, <code>for</code>, <code>while</code>, <code>do</code> or arrow function (<code>() =&gt; page.click(…)</code>) without braces, or on a line where no statement starts;</li><li>in a file written on disk since the run started, or unsaved as it started: Piwi follows a file through the edits the editor makes, not through another program&#39;s;</li><li>that the test went on from: an action answers the stop it was offered at.</li></ul><p>Assert and Assert a region check this before anything opens in the test&#39;s window. Code that arrives while you type in its file is not written into the changed text: a warning offers <strong>Copy the code</strong>.</p><h2 id="mock-a-request" tabindex="-1">Mock a request <a class="header-anchor" href="#mock-a-request" aria-label="Permalink to &quot;Mock a request&quot;">​</a></h2><p>In a run Piwi started, each worker keeps the text answers its test&#39;s pages received for <code>fetch</code> and XHR requests, the latest 50, 256 KB each at most, in its memory only. <strong>Mock a request</strong> lists them, the latest first, by method and URL (type to filter on the URL), with the status, the type, the size (<code>no size</code> when the response did not say) and when it finished in the test. Only the answer you choose is read whole:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> page.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">route</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;**/api/shipping?country=FR&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">route</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  route.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fulfill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    json: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;price&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;hidden&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>It is written as <a href="./mock-requests.html#mock-this-response">Piwi Picker&#39;s Network tab</a> writes one, the body inline whatever its size, with what it hides:</p><ul><li><strong>Credentials.</strong> A field named like a password, a token, a key, a signature or a session is written as <code>&lt;hidden&gt;</code>, whatever it holds, and so is a value shaped like a credential anywhere in the body, by the <a href="./mock-requests.html#mock-this-response">rule Piwi Picker&#39;s mocks follow</a>: ids, hashes and cursors stay. The URL pattern matches such a value with a wildcard, and keeps the host. The list hides them too. Headers, cookies included, are never written.</li><li><strong>Warnings.</strong> The editor says how many values it wrote as <code>&lt;hidden&gt;</code>, that a body neither JSON nor a form was written as it came (read it before you commit it), and that a body seems to hold an email address or a phone number (replace it with made-up data).</li></ul><h2 id="the-locator-at-the-cursor" tabindex="-1">The locator at the cursor <a class="header-anchor" href="#the-locator-at-the-cursor" aria-label="Permalink to &quot;The locator at the cursor&quot;">​</a></h2><p>While a test is stopped, put the cursor on a line of the stopped file: its end says how many elements the line&#39;s locator matches on the stopped page, <code>Piwi: 3 matches</code>, <code>1 match</code> or <code>no match</code>, and where the pause bar shows, the matches are outlined in the page. Edit the locator and it is counted again. The outline goes when the cursor leaves the file or the test goes on.</p><p>The locator must start from the page the test stopped on, as the code written there would: a line of <code>adminPage</code> at a stop on <code>page</code> may be another page, and says so for a moment instead of a count. Only the stopped file&#39;s lines are counted, and a line without a locator says nothing.</p><h2 id="a-failure" tabindex="-1">A failure <a class="header-anchor" href="#a-failure" aria-label="Permalink to &quot;A failure&quot;">​</a></h2><p>In a run Piwi started, a failing test holds its page once the test function, its hooks and its fixtures are done, instead of closing it, when someone can see it: in a headed browser, where the pause bar shows the failure (a run started with breakpoints, or for a spec with <code>page.pause()</code>, is headed), or while Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a> is open. The editor shows it as a stop of its own, at the line where the error entered the test&#39;s code, or at the call a test timeout cut short:</p><p><code>Failed · Timed out 5000ms waiting for getByRole(&#39;button&#39;, { name: &#39;Apply&#39; }) · attempt 2</code> Resume Pick Record …</p><p><strong>Resume</strong> lets the test end as it failed (<strong>Step</strong> and <strong>Finish</strong> do the same); <strong>Pick</strong> replaces the failing locator, <strong>Record</strong> writes the steps that were missing above the failing line, and the code actions work as at any stop. Every attempt that fails is held, never an expected failure. A headless failure in any other run, such as a plain <strong>Run</strong>, goes on at once, and the editor shows nothing of it.</p><p>The run reports the failure as it happened. Piwi&#39;s evidence of it is the page at the failure: the requests, console entries and dialogs of the hold are not recorded. Playwright&#39;s own trace and video go on through it.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Runs Piwi started only</strong>, with a reporter that takes the actions; an editor extension older than the reporter holds no failure.</li><li><strong>Assert offers what a recording&#39;s check panel offers</strong>: a value, a text, a name, visible or hidden, enabled or disabled, with no <code>toBeChecked</code> or <code>toHaveCount</code> choice.</li><li><strong>Assert a region</strong> leaves out the value of a password, one-time code or card field, in a shadow root too, and a link whose URL holds a credential.</li><li><strong>Mock a request</strong> knows <code>fetch</code> and XHR answers with a text body only; one the browser no longer holds cannot be mocked, which the editor says.</li><li><strong>The count needs a locator Piwi reads</strong>: literal arguments, starting from a page in scope on the line.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the controls, the paused line, a headless test&#39;s page.</li><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the pause bar, Pick a locator and Record here.</li><li><a href="./mock-requests.html">Mock and slow down requests</a>: the same mocks from Piwi Picker&#39;s Network tab.</li><li><a href="./recorded-code.html">Recorded code</a>: what a recording writes, and how the config shapes it.</li></ul>`,29))])}const b=a(c,[["render",p]]);export{y as __pageData,b as default};
